// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the caller and the caddress (callee) but the crucial deciding value is the empty array
    function testFuzz_property(address caller, address callee) public {
        // keep fuzzed addresses wide but non-zero to be admissible
        vm.assume(caller != address(0));
        vm.assume(callee != address(0));

        address[] memory tosEmpty = new address[](0);

        // Try-reference behavior: call and observe whether it reverts
        bool ok;
        try c.transfer(caller, callee, tosEmpty, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: reference C always REVERTS (ok == false) when _tos is empty.
        // The mutant (with require(_tos.length >= 0)) will make ok == true for some inputs,
        // so this assertion will fail on the buggy version for these inputs.
        assertTrue(ok == false);
    }
}
